export const carriers: Carrier[] = [...curatedCarriers,...directory.map(([id,label,region,aliases,source])=>({id,label,region,regions:[region],aliases,source,assetSource:"",icon:"",reference:true}))];
const byId = new Map(carriers.map(c=>[c.id,c]));
export const findCarrier = (id:string) => byId.get(id);
export const carrierCoverage = new Set(carriers.flatMap(c=>c.regions).filter(c=>c!=="INT")).size;
